// Selected-marker interpretation only. No diplotype or phenotype inference.
import {RULE_VERSION,MARKERS,MARKER_EVIDENCE} from './marker-rules.mjs';
export {RULE_VERSION,MARKERS,MARKER_EVIDENCE};
export const MAX_BYTES=25*1024*1024;
export const MAX_ROWS=1200000;
const ORIGINAL_SAMPLE='# This data file generated by 23andMe (SYNTHETIC EXAMPLE ONLY)\n# We are using reference human assembly build 37.\n# Genotypes are reported on the positive strand.\n# rsid\tchromosome\tposition\tgenotype\nrs4244285\t10\t96541616\tAG\nrs4986893\t10\t96540410\tGG\nrs12248560\t10\t96521657\t--\nrs4149056\t12\t21331549\tTT\n';
const DPYD_REFERENCE='rs3918290\t1\t97915614\tCC\nrs55886062\t1\t97981343\tAA\nrs67376798\t1\t97547947\tTT\nrs75017182\t1\t98045449\tGG\n';
export const SAMPLE=ORIGINAL_SAMPLE+DPYD_REFERENCE;
export const MULTIGENE_SAMPLE=SAMPLE.replace('21331549\tTT','21331549\tCT');
export const DPYD_SAMPLE=SAMPLE.replace('96541616\tAG','96541616\tGG').replace('96521657\t--','96521657\tCC').replace('97915614\tCC','97915614\tCT').replace('98045449\tGG','98045449\t--');
function fail(message,code='records'){const error=new Error(message);error.code=code;throw error;}
export function parseGenetics(text){
 if(typeof text!=='string'||new TextEncoder().encode(text).length>MAX_BYTES)fail('Choose a plain text file no larger than 25 MB.','size');
 if(/^PK[\u0003\u0005\u0007]/.test(text))fail('This is a ZIP archive.','archive');
 if(/^%PDF-/.test(text))fail('This is a PDF document.','document');
 if(/^##fileformat=VCF/m.test(text))fail('This is a VCF file.','vcf');
 if(!text.trim())fail('The selected file is empty.','empty');
 if(text.includes('\u0000'))fail('This is not a supported plain text export. Unzip the original download first.','format');
 let provider=false,positive=false,negative=false,header=false,count=0,duplicates=0;
 const builds=new Set(),seen=new Map(),target=new Map();
 const ids=new Set(MARKERS.map(m=>m.id)),positions=new Set(MARKERS.map(m=>`${m.chromosome}:${m.position}`));
 // Discard unrelated genotypes immediately; keep only the selected loci.
 for(const raw of text.replace(/^\uFEFF/,'').split(/\r?\n/)){
  const line=raw.trim();if(!line)continue;
  if(line.startsWith('#')){
   if(/23andme/i.test(line))provider=true;
   if(/(?:positive|plus|\(\+\))\s*(?:\(\+\)\s*)?strand/i.test(line))positive=true;
   if(/(?:negative|minus|\(-\))\s*(?:\(-\)\s*)?strand/i.test(line))negative=true;
   for(const m of line.matchAll(/(?:build\s*|GRCh\s*|hg)(\d+)/gi))builds.add(m[1]==='19'?'37':m[1]);
   if(/^#\s*rsid\s+chromosome\s+position\s+genotype\s*$/i.test(line))header=true;
   continue;
  }
  count++;if(count>MAX_ROWS)fail('This file has too many records. The limit is 1,200,000.');
  if(!header)fail('The expected rsid / chromosome / position / genotype header is missing.','header');
  const cols=line.split('\t');
  if(cols.length!==4)fail(`Record ${count} does not have four tab-separated columns.`);
  const [id,chr,pos,reported]=cols.map(s=>s.trim());
  if(!/^(rs\d+|i\d+)$/.test(id)||!/^(?:[1-9]|1\d|2[0-2]|X|Y|MT)$/.test(chr)||!/^\d+$/.test(pos)||!Number.isSafeInteger(Number(pos))||Number(pos)<1||!/^(?:[ACGTDI]{1,2}|--)$/.test(reported))fail(`Record ${count} is not a supported 23andMe record.`);
  if(!ids.has(id)&&!positions.has(`${chr}:${pos}`))continue;
  if(!ids.has(id))fail('A selected locus uses an unsupported marker identifier. No result was inferred.');
  const m=MARKERS.find(m=>m.id===id);
  if(chr!==m.chromosome||Number(pos)!==m.position)fail('A selected marker does not match its build 37 location. Check the original export.','location');
  const call=reported.split('').sort().join('');
  if(seen.has(id)){
   if(seen.get(id)!==call)fail('Conflicting records were found for a selected marker. No findings were produced.','conflict');
   duplicates++;continue;
  }
  seen.set(id,call);target.set(id,call);
 }
 if(!provider)fail('This reader supports 23andMe text exports with the original header.','header');
 if(builds.size!==1||!builds.has('37'))fail('Only an unambiguous build 37 export is supported. No genome-build conversion was attempted.','build');
 if(!positive||negative)fail('The header must specify positive-strand genotypes without conflicting strand information.','strand');
 if(!header||!count)fail('No genetic records were found.');
 const findings=MARKERS.map(m=>{
  const genotype=target.get(m.id);
  const state=genotype===undefined?'missing':genotype==='--'?'no-call':genotype.length!==2||[...genotype].some(b=>b!==m.reference&&b!==m.alternate)?'unsupported':genotype.includes(m.alternate)?'detected':'not-detected';
  return {...m,genotype:genotype??null,state,copies:state==='detected'?[...genotype].filter(b=>b===m.alternate).length:null};
 });
 return {ruleVersion:RULE_VERSION,evidence:MARKER_EVIDENCE,build:'GRCh37',strand:'positive',records:count,duplicates,covered:findings.filter(m=>['detected','not-detected'].includes(m.state)).length,findings,phenotype:null,diplotype:null};
}
export function summarize(result){
 const detected=result.findings.filter(m=>m.state==='detected');
 const unresolved=result.findings.some(m=>!['detected','not-detected'].includes(m.state));
 if(detected.length)return {title:'A medication-related marker was found.',body:`${detected.length===1?'One selected variant is':`${detected.length} selected variants are`} present in the reported data. ${unresolved?'Some selected markers remain unresolved. ':''}These findings do not establish your overall gene function or a medication recommendation.`};
 if(unresolved)return {title:'The picture is incomplete.',body:'No selected variant was detected in the interpretable calls, but some markers are missing or unresolved. This is not a normal-metabolism result.'};
 return {title:'No selected variants were detected.',body:'The reported calls do not contain the specific variants assessed here. Other variants in these genes were not evaluated; normal metabolism cannot be established from this result.'};
}
